CREATE TABLE `notification_logs` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`channel` ENUM('EMAIL') NOT NULL DEFAULT 'EMAIL',`kind` VARCHAR(80) NOT NULL,`target_type` VARCHAR(80) NOT NULL,`target_public_id` CHAR(36) NULL,`recipient` VARCHAR(254) NOT NULL,`subject` VARCHAR(255) NOT NULL,`body` TEXT NOT NULL,`status` ENUM('PENDING', 'SENT', 'FAILED', 'SKIPPED') NOT NULL DEFAULT 'PENDING',`attempts` TINYINT UNSIGNED NOT NULL DEFAULT 0,`last_error` VARCHAR(500) NULL,`sent_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `notification_logs_public_id_key` (`public_id`),INDEX `notification_logs_tenant_id_created_at_idx` (`tenant_id`,`created_at`),INDEX `notification_logs_tenant_id_status_idx` (`tenant_id`,`status`),INDEX `notification_logs_target_type_target_public_id_idx` (`target_type`,`target_public_id`),CONSTRAINT `notification_logs_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
